// Topic Selector — port of topic-selector.js, runs in n8n Code node.
// Reads Notion query response, dedups vs published log (static workflow data),
// picks top N, maps each to format.

const SCORE_MIN = 3.0;
const N_PICKS = 2;

const staticData = $getWorkflowStaticData('global');
staticData.publishedIds = staticData.publishedIds || []; // persisted across runs in n8n
const usedIds = new Set(staticData.publishedIds);

const input = $input.first().json;
const results = input.results || [];

function pickFormat(item) {
  const blob = (item.title + ' ' + item.why).toLowerCase();
  if (/\b(framework|steps|checklist|playbook|process|how to)\b/.test(blob)) return 'carousel';
  if (/\b(\d+%|percent|vs\.?|comparison|benchmark|study|survey)\b/.test(blob)) return 'infographic';
  return 'text-post';
}

function isoWeek(d) {
  const t = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
  const dayNum = t.getUTCDay() || 7;
  t.setUTCDate(t.getUTCDate() + 4 - dayNum);
  const yearStart = new Date(Date.UTC(t.getUTCFullYear(), 0, 1));
  const wk = Math.ceil(((t - yearStart) / 86400000 + 1) / 7);
  return t.getUTCFullYear() + '-W' + String(wk).padStart(2, '0');
}

const items = results.map(p => ({
  source_id: p.id,
  title: p.properties.Title?.title?.[0]?.plain_text?.trim() || '(untitled)',
  url: p.properties.URL?.url || '',
  score: p.properties.haiku_score?.number ?? 0,
  why: p.properties.why?.rich_text?.[0]?.plain_text?.trim() || '',
  permalink: p.properties['Slack Permalink']?.url || '',
  domain: p.properties.domain?.select?.name || ''
}));

const fresh = items.filter(i => !usedIds.has(i.source_id) && i.score >= SCORE_MIN);
const picks = fresh.slice(0, N_PICKS).map(i => ({ ...i, format: pickFormat(i), week: isoWeek(new Date()) }));

if (picks.length === 0) {
  // Skip the run, emit nothing → Slack send-on-empty handled downstream.
  return [{ json: { skip: true, queried: items.length, used: usedIds.size, fresh: 0 } }];
}

return picks.map(p => ({ json: p }));

// Build the format-specific generation prompt + system prompt.
// Brand voice block is embedded here (keep in sync with content/engine/brand-voice.md).

const BRAND_VOICE = `You are drafting a LinkedIn post for CounterbenchAI.

AUDIENCE: PI attorneys, solo to 10-attorney firms. Skeptical by profession. Care about case outcomes, response time, data security. Do NOT care about tech stack.

COUNTER-NARRATIVE (must surface naturally in body, never collapse): "AI tools AND the team to run them. You don't have to choose." Free tool directory at top of funnel + $3,750-$6,500/mo Paralegal Teams retainer at the bottom.

VOICE: direct, data-forward, formal but not stiff. Short paragraphs. Lead with outcome, not technology. Reference specifics (case types, time/cost savings).

HARD BANS:
- No em-dashes. Hyphens only.
- No buzzwords: AI-powered, cutting-edge, intelligent, revolutionary, seamless, leverage, game-changer.
- No first line starting with "I".
- No hashtags, no semicolons, no comment-bait CTAs.
- No invented case names, no fabricated stats.
- No claims beyond what the source signal supports.

FORMAT-SPECIFIC RULES BELOW.`;

const FORMATS = {
  'text-post': `\n\nFORMAT: TEXT POST\n- 900-1300 characters.\n- Hook = standalone first line that works before the "see more" cut.\n- 1-3 line paragraphs with blank line between.\n- Story arc: setup -> stakes/insight -> takeaway.\n- End with ONE question OR ONE CTA, not both.\n- No URLs in body (link goes in first comment).\n- Output ONLY the post body. No preamble, no labels.`,
  'carousel': `\n\nFORMAT: LINKEDIN CAROUSEL (5-8 slides)\n- Slide 1: pain hook (the problem the attorney feels).\n- Slides 2-N-1: framework / steps / data points. One idea per slide. Max 2 sentences each.\n- Final slide: the counter-narrative + single CTA.\n- Output as JSON: { "slides": [{ "n": 1, "headline": "...", "body": "..." }, ...] }`,
  'infographic': `\n\nFORMAT: INFOGRAPHIC CONCEPT\n- Pick ONE stat or comparison from the source that makes understaffing pain visceral.\n- Output as JSON: { "chart_type": "bar|comparison|stat-callout", "headline": "...", "data_points": [...], "caption": "...", "caveat": "required: what the source does NOT establish, so design step does not over-claim" }`
};

const item = $input.first().json;
if (item.skip) return [{ json: item }];

const userPrompt = `SOURCE SIGNAL\n- Title: ${item.title}\n- URL: ${item.url}\n- Domain: ${item.domain}\n- Haiku score: ${item.score}\n- Why it scored: ${item.why}\n- Slack permalink: ${item.permalink}\n\nWrite the ${item.format} per the format rules above. Source-discipline: do NOT invent specifics beyond what the signal supports. If the signal is thin, write to the general pattern and avoid named cases or fabricated stats.`;

return [{
  json: {
    ...item,
    system_prompt: BRAND_VOICE + FORMATS[item.format],
    user_prompt: userPrompt
  }
}];

// Extract Claude response, attach to item context for Slack post.
const prior = $('Code: Build Prompt').first().json;
const resp = $input.first().json;
const draftText = resp.content?.[0]?.text || '(generation failed)';
return [{
  json: {
    ...prior,
    draft: draftText,
    generated_at: new Date().toISOString()
  }
}];

